#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
map<int, int> mpp;
vector<int> ans(2, 0);
for(auto i = 0; i < nums.size(); i++) mpp[nums[i]] = i;

for(auto i : nums){
    if(mpp.count(target - i)){
        ans[0] = mpp[target - i];
        ans[1] = mpp[i];
    }
}
return ans;
    }
};

